import os,re
from collections import Counter,deque
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
def f(g):
    h,w=len(g),len(g[0])
    cnt=Counter(x for r in g for x in r)
    rare=[c for c,v in cnt.items() if v<=3]
    adj=set()
    for i in range(h):
        for j in range(w):
            if g[i][j] in rare:
                for a,b in [(i+1,j),(i-1,j),(i,j+1),(i,j-1)]:
                    if 0<=a<h and 0<=b<w: adj.add(g[a][b])
    corridor=min([c for c in adj if c not in rare],key=lambda c:cnt[c])
    seeds=[(i,j,g[i][j]) for i in range(h) for j in range(w) if g[i][j] in rare]
    INF=10**9; dist=[[INF]*w for _ in range(h)]; q=deque()
    for si,sj,col in seeds:
        dist[si][sj]=0;q.append((si,sj))
    while q:
        p=q.popleft(); a=p[0]; b=p[1]
        for di,dj in((1,0),(-1,0),(0,1),(0,-1)):
            na,nb=a+di,b+dj
            if 0<=na<h and 0<=nb<w and g[na][nb]==corridor and dist[na][nb]==INF:
                dist[na][nb]=dist[a][b]+1;q.append((na,nb))
    co2={(i+j)%2:col for i,j,col in sorted(seeds)}
    out=[r[:] for r in g]
    for i in range(h):
        for j in range(w):
            if g[i][j]==corridor and dist[i][j]<INF:
                out[i][j]=co2[(i+j)%2]
    return out
for key in ['Demo pair 1 input','Demo pair 2 input']:
    P=f(G[key]); O=G[key.replace('input','output')]
    print(key,"match:",P==O)
T=f(G['Test input'])
